// Regenerate independent fixtures with Node's OpenSSL-backed signing API:
// node test/fixtures/generate-jwt.mjs
// These are disposable test keys, never production credentials.
import { createHmac, generateKeyPairSync, sign, constants } from 'node:crypto';
import { writeFileSync } from 'node:fs';
const b64 = (data) => Buffer.from(data).toString('base64url');
const secret = ' exact 中文 secret 🌍\n';
const rsa = generateKeyPairSync('rsa', { modulusLength: 2048 });
const wrongRsa = generateKeyPairSync('rsa', { modulusLength: 2048 });
const vectors = [];
for (const alg of ['HS256', 'HS384', 'HS512', 'RS256', 'RS384', 'RS512', 'PS256', 'PS384', 'PS512', 'ES256', 'ES384', 'ES512']) {
  const input = `${b64('{ "typ": "JWT", "alg": "' + alg + '" }\r\n')}.${b64('{"sub":"你好🌍","exp":1}\n')}`;
  if (alg.startsWith('HS')) {
    vectors.push({ alg, token: `${input}.${createHmac(`sha${alg.slice(2)}`, secret).update(input).digest('base64url')}` });
    continue;
  }
  const ec = alg.startsWith('ES');
  const namedCurve = alg === 'ES256' ? 'prime256v1' : alg === 'ES384' ? 'secp384r1' : 'secp521r1';
  const pair = ec ? generateKeyPairSync('ec', { namedCurve }) : rsa;
  const wrong = ec ? generateKeyPairSync('ec', { namedCurve }) : wrongRsa;
  const options = ec ? { key: pair.privateKey, dsaEncoding: 'ieee-p1363' }
    : alg.startsWith('PS') ? { key: pair.privateKey, padding: constants.RSA_PKCS1_PSS_PADDING, saltLength: Number(alg.slice(2)) / 8 } : pair.privateKey;
  const signature = sign(`sha${alg.slice(2)}`, Buffer.from(input), options);
  vectors.push({ alg, token: `${input}.${b64(signature)}`,
    pem: pair.publicKey.export({ type: 'spki', format: 'pem' }).toString(),
    jwk: pair.publicKey.export({ format: 'jwk' }),
    wrongPem: wrong.publicKey.export({ type: 'spki', format: 'pem' }).toString(),
    privatePem: pair.privateKey.export({ type: 'pkcs8', format: 'pem' }).toString(),
    privateJwk: pair.privateKey.export({ format: 'jwk' }),
    ...(ec ? { derToken: `${input}.${b64(sign(`sha${alg.slice(2)}`, Buffer.from(input), pair.privateKey))}` } : {}) });
}
const small = generateKeyPairSync('rsa', { modulusLength: 1024 });
writeFileSync(new URL('./jwt-vectors.ts', import.meta.url), '// Generated by generate-jwt.mjs using Node/OpenSSL; no production keys.\nexport const jwtVectors = ' + JSON.stringify(vectors, null, 2) + ' as const;\nexport const smallRsaPem = ' + JSON.stringify(small.publicKey.export({ type: 'spki', format: 'pem' }).toString()) + ';\n');
